from dataclasses import dataclass
@dataclass(frozen=True, slots=True, repr=False)
class A:
    def __repr__(self):
        return "A"
_A: A = A()
@dataclass(frozen=True, slots=True, repr=False)
class B:
    def __repr__(self):
        return "B"
_B: B = B()
@dataclass(frozen=True, slots=True, repr=False)
class C:
    def __repr__(self):
        return "C"
_C: C = C()
T = A | B | C
def f(t: T, x: None):
    if isinstance(t, A):
        print("a")
    elif isinstance(t, B):
        pass
    return print("done")
